// --- Scientific literacy index -----------------------------------------
// items: { F2201, F2202, F2203, F2204, F2211 } raw values 1..4 | 98 | null
function recodeTrueStatement(x) {           // correct statements
  if (x === null || x === undefined) return null;
  if (x === 1 || x === 2 || x === 98) return 0;
  if (x === 3) return 1;
  if (x === 4) return 2;
  return null;
}
function recodeFalseStatement(x) {          // false statements
  if (x === null || x === undefined) return null;
  if (x === 3 || x === 4 || x === 98) return 0;
  if (x === 2) return 1;
  if (x === 1) return 2;
  return null;
}
function computeIdxSL(items) {
  const rec = [
    recodeTrueStatement(items.F2201),
    recodeTrueStatement(items.F2202),
    recodeFalseStatement(items.F2203),
    recodeFalseStatement(items.F2204),
    recodeFalseStatement(items.F2211)
  ].filter(v => v !== null);
  if (rec.length === 0) return null;        // SPSS MEAN: missing if no valid args
  return rec.reduce((a, b) => a + b, 0) / rec.length;
}

// --- Classification ----------------------------------------------------
// answers: raw values for F0505, F1504, F1505, F1801..F1810, F1901..F1907,
//          F2003 (1..5 | 98 | null) and F2201..F2204, F2211 (1..4 | 98 | null)
function classify(answers) {
  const dontKnowToNull = x => (x === null || x === undefined || x === 98) ? null : x;

  // Filter replication: no interest at all -> item scored 1 (as in CATI)
  let f1504rec = dontKnowToNull(answers.F1504);
  if (dontKnowToNull(answers.F0505) === 1) f1504rec = 1;

  const values = {
    F0505: dontKnowToNull(answers.F0505),
    F1504_rec: f1504rec,
    F1505: dontKnowToNull(answers.F1505),
    F1801: dontKnowToNull(answers.F1801),
    F1802: dontKnowToNull(answers.F1802),
    F1803: dontKnowToNull(answers.F1803),
    F1804: dontKnowToNull(answers.F1804),
    F1806: dontKnowToNull(answers.F1806),
    F1808: dontKnowToNull(answers.F1808),
    F1809: dontKnowToNull(answers.F1809),
    F1810: dontKnowToNull(answers.F1810),
    F1901: dontKnowToNull(answers.F1901),
    F1902: dontKnowToNull(answers.F1902),
    F1903: dontKnowToNull(answers.F1903),
    F1904: dontKnowToNull(answers.F1904),
    F1905: dontKnowToNull(answers.F1905),
    F1906: dontKnowToNull(answers.F1906),
    F1907: dontKnowToNull(answers.F1907),
    F2003: dontKnowToNull(answers.F2003),
    idx_SL: computeIdxSL(answers)
  };

  // Missing handling exactly as in the syntax
  const env = {};
  for (const v of CLUSTER_VARS) {
    const x = values[v];
    if (x === null) {
      env[v + "_lg"] = IMPUTATION[v];
      env[v + "_lg_m"] = 1;
    } else {
      env[v + "_lg"] = x;
      env[v + "_lg_m"] = 0;
    }
  }
  // Note: idx_SL has no missing-indicator term in the equations (as in the syntax);
  // env["idx_SL_lg_m"] is simply never referenced.

  const logits = ["1", "2", "3", "4"].map(k => {
    const eq = EQUATIONS[k];
    let s = eq.i;
    for (const [c, a, b] of eq.t) s += (b === null) ? c * env[a] : c * env[a] * env[b];
    return s;
  });

  // Softmax
  const mx = Math.max(...logits);
  const exps = logits.map(l => Math.exp(l - mx));
  const tot = exps.reduce((a, b) => a + b, 0);
  const probs = exps.map(e => e / tot);

  // SPSS sequential IFs with ">=": among ties, the higher-numbered cluster wins
  let cluster = 1;
  for (let i = 1; i < 4; i++) if (probs[i] >= probs[cluster - 1]) cluster = i + 1;

  // Recode to ordinal typology: 1=Sciencephiles, 2=Critically Interested,
  // 3=Passive Supporters, 4=Disengaged
  const ORDINAL = { 1: 3, 2: 1, 3: 2, 4: 4 };
  const segment = ORDINAL[cluster];

  // Probabilities re-keyed by ordinal segment
  const pOrd = {};
  for (let c = 1; c <= 4; c++) pOrd[ORDINAL[c]] = probs[c - 1];

  return {
    segment: segment,
    label: SEGMENT_LABELS[segment].en,
    probabilities: pOrd,           // {1:..,2:..,3:..,4:..} keyed by ordinal segment
    idx_SL: values.idx_SL,
    nMissing: CLUSTER_VARS.reduce((n, v) => n + (values[v] === null ? 1 : 0), 0)
  };
}


