function classify10(answers) {
  // raw values: 1..5 valid; 98 / null / undefined -> missing
  var x = new Array(10), m = new Array(10);
  for (var i = 0; i < 10; i++) {
    var v = answers[TEN_ORDER[i]];
    var num = (v === null || v === undefined) ? NaN : Number(v);
    if (!isFinite(num) || num < 1 || num > 5) { x[i] = TEN_IMPUTE[i]; m[i] = 1; }
    else { x[i] = num; m[i] = 0; }
  }
  var logits = new Array(4);
  for (var k = 0; k < 4; k++) {
    var C = TEN_CLUSTERS[k], s = C.b0;
    for (var a = 0; a < 10; a++) { s += C.lin[a] * x[a] + C.mis[a] * m[a]; }
    var q = C.quad;
    for (var t = 0; t < q.length; t++) { s += q[t][2] * x[q[t][0]] * x[q[t][1]]; }
    logits[k] = s;
  }
  var mx = Math.max(logits[0], logits[1], logits[2], logits[3]);
  var e = [Math.exp(logits[0]-mx), Math.exp(logits[1]-mx), Math.exp(logits[2]-mx), Math.exp(logits[3]-mx)];
  var tot = e[0]+e[1]+e[2]+e[3];
  var p = [e[0]/tot, e[1]/tot, e[2]/tot, e[3]/tot];
  var best = 0;
  for (var c = 1; c < 4; c++) if (p[c] > p[best]) best = c;
  // supplement cluster order: 1=Passive Supporters, 2=Sciencephiles,
  // 3=Critically Interested, 4=Disengaged  ->  platform ordinal segments
  var ORD10 = [3, 1, 2, 4];
  var pOrd = {};
  for (var c2 = 0; c2 < 4; c2++) pOrd[ORD10[c2]] = p[c2];
  var seg = ORD10[best];
  return {
    segment: seg,
    label: SEGMENT_LABELS[seg].en,
    probabilities: pOrd,
    idx_SL: computeIdxSL(answers),
    nMissing: m.reduce(function(a,b){ return a+b; }, 0)
  };
}

if (typeof module !== "undefined") module.exports = { classify, classify10, computeIdxSL, SEGMENT_LABELS, CLUSTER_VARS, TEN_ITEMS };
